class Solution:
    def lastNonEmptyString(self, s: str) -> str:
        cnt = Counter(s)
        last = {c: i for i, c in enumerate(s)}
        mx = max(cnt.values())
        return ''.join(c for c, i in sorted(last.items(), key=lambda kv: kv[1])
                       if cnt[c] == mx)

