class Solution {
public:
    string lastNonEmptyString(string s) {
        int cnt[26] = {}, lst[26] = {};
        for (int i = 0; i < (int)s.size(); i++) {
            cnt[s[i]-'a']++; lst[s[i]-'a'] = i;
        }
        int mx = *max_element(cnt, cnt+26);
        vector<pair<int,char>> v;
        for (int c = 0; c < 26; c++)
            if (cnt[c] == mx) v.push_back({lst[c], (char)('a'+c)});
        sort(v.begin(), v.end());
        string r;
        for (auto& [i, c] : v) r += c;
        return r;
    }
};

