class Solution {
    public String lastNonEmptyString(String s) {
        int[] cnt = new int[26], lst = new int[26];
        for (int i = 0; i < s.length(); i++) {
            cnt[s.charAt(i)-'a']++; lst[s.charAt(i)-'a'] = i;
        }
        int mx = 0;
        for (int c : cnt) mx = Math.max(mx, c);
        List<int[]> v = new ArrayList<>();
        for (int c = 0; c < 26; c++)
            if (cnt[c] == mx) v.add(new int[]{lst[c], c});
        v.sort((a, b) -> a[0] - b[0]);
        StringBuilder sb = new StringBuilder();
        for (int[] p : v) sb.append((char)('a'+p[1]));
        return sb.toString();
    }
}

