var lastNonEmptyString = function(s) {
    const cnt = Array(26).fill(0), lst = Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        cnt[s.charCodeAt(i)-97]++; lst[s.charCodeAt(i)-97] = i;
    }
    const mx = Math.max(...cnt);
    const v = [];
    for (let c = 0; c < 26; c++) if (cnt[c] === mx) v.push([lst[c], c]);
    v.sort((a, b) => a[0] - b[0]);
    return v.map(p => String.fromCharCode(97 + p[1])).join('');
};

