class Solution:
    def lastNonEmptyString(self, s: str) -> str:
        pos = defaultdict(deque)
        for i, c in enumerate(s): pos[c].append(i)
        rounds = max(len(d) for d in pos.values())
        alive = []
        for c, d in pos.items():
            if len(d) == rounds: alive.append(d[-1])
        alive.sort()
        return ''.join(s[i] for i in alive)

