class Solution {
public:
    string lastNonEmptyString(string s) {
        vector<deque<int>> pos(26);
        for (int i = 0; i < (int)s.size(); i++) pos[s[i]-'a'].push_back(i);
        int rounds = 0;
        for (auto& d : pos) rounds = max(rounds, (int)d.size());
        vector<int> alive;
        for (int c = 0; c < 26; c++)
            if ((int)pos[c].size() == rounds) alive.push_back(pos[c].back());
        sort(alive.begin(), alive.end());
        string r;
        for (int i : alive) r += s[i];
        return r;
    }
};

