class Solution {
    public String lastNonEmptyString(String s) {
        List<ArrayDeque<Integer>> pos = new ArrayList<>();
        for (int c = 0; c < 26; c++) pos.add(new ArrayDeque<>());
        for (int i = 0; i < s.length(); i++) pos.get(s.charAt(i)-'a').add(i);
        int rounds = 0;
        for (var d : pos) rounds = Math.max(rounds, d.size());
        List<Integer> alive = new ArrayList<>();
        for (int c = 0; c < 26; c++)
            if (pos.get(c).size() == rounds) alive.add(pos.get(c).peekLast());
        Collections.sort(alive);
        StringBuilder sb = new StringBuilder();
        for (int i : alive) sb.append(s.charAt(i));
        return sb.toString();
    }
}

