var lastNonEmptyString = function(s) {
    const pos = Array.from({length: 26}, () => []);
    for (let i = 0; i < s.length; i++) pos[s.charCodeAt(i)-97].push(i);
    const rounds = Math.max(...pos.map(d => d.length));
    const alive = [];
    for (const d of pos) if (d.length === rounds) alive.push(d[d.length-1]);
    alive.sort((a, b) => a - b);
    return alive.map(i => s[i]).join('');
};
